INSERT INTO public.questions (language, level, category, question_type, question_text, options, correct_answer, explanation, image_url, audio_url, points, max_plays, order_hint, is_active) VALUES
('es','B1','vocabulary','mcq','"El precio del curso es asequible para los estudiantes." En este contexto, «asequible» significa...','["razonable","elevado","obligatorio","provisional"]','razonable','"Asequible" indica que algo se puede pagar sin dificultad.',NULL,NULL,1,5,200,true),
('es','B1','vocabulary','mcq','Después de la entrevista, la empresa ______ una decisión.','["tomó","hizo","puso","dio"]','tomó','La colocación fija es "tomar una decisión".',NULL,NULL,1,5,201,true),
('es','B1','vocabulary','mcq','"Los recursos son escasos." ¿Cuál es el antónimo de «escasos»?','["abundantes","limitados","reducidos","insuficientes"]','abundantes','"Escaso" se opone a "abundante".',NULL,NULL,1,5,202,true),
('es','B1','vocabulary','mcq','«Estoy hasta las narices de esperar» significa que...','["estoy harto","estoy contento","estoy enfermo","tengo prisa"]','estoy harto','Expresión coloquial que indica hartazgo.',NULL,NULL,1,5,203,true),
('es','B1','vocabulary','mcq','Para inscribirte debes ______ el formulario.','["rellenar","vaciar","cumplir","redactar"]','rellenar','Con un formulario se usa el verbo "rellenar".',NULL,NULL,1,5,204,true),
('es','B2','vocabulary','mcq','«Un logro rotundo» es un logro...','["indiscutible","discreto","provisional","dudoso"]','indiscutible','"Rotundo" refuerza la idea de algo total y claro.',NULL,NULL,1,5,210,true),
('es','B2','vocabulary','mcq','El ministro ______ un discurso ante el Parlamento.','["pronunció","dijo","habló","comentó"]','pronunció','La colocación culta es "pronunciar un discurso".',NULL,NULL,1,5,211,true),
('es','B2','vocabulary','mcq','Los resultados fueron buenos; ______, conviene ser prudentes.','["no obstante","por lo tanto","es decir","además"]','no obstante','El conector expresa contraste.',NULL,NULL,1,5,212,true),
('es','B2','vocabulary','mcq','En un correo formal, ¿cuál es la fórmula de despedida más adecuada?','["Le saluda atentamente","Un abrazo fuerte","Nos vemos pronto","Chao"]','Le saluda atentamente','Las demás pertenecen al registro informal.',NULL,NULL,1,5,213,true),
('es','B2','vocabulary','mcq','«Estar en la cuerda floja» significa...','["encontrarse en una situación precaria","tener mucha suerte","trabajar en un circo","estar muy relajado"]','encontrarse en una situación precaria','Locución figurada de inestabilidad o riesgo.',NULL,NULL,1,5,214,true),
('es','C1','vocabulary','mcq','El discurso resultó ______: nadie logró descifrar su verdadera intención.','["críptico","diáfano","escueto","ameno"]','críptico','"Críptico" significa oscuro o de difícil interpretación.',NULL,NULL,1,5,220,true),
('es','C1','vocabulary','mcq','«Se entregaron sendos informes a los dos responsables.» ¿Qué significa «sendos»?','["uno para cada uno","dos informes muy largos","informes idénticos","informes anteriores"]','uno para cada uno','"Sendos" significa uno para cada una de las personas mencionadas.',NULL,NULL,1,5,221,true),
('es','C1','vocabulary','mcq','La decisión podría ______ un precedente peligroso.','["sentar","poner","hacer","dejar"]','sentar','La colocación fija es "sentar un precedente".',NULL,NULL,1,5,222,true),
('es','C1','vocabulary','mcq','«Un elogio velado» es un elogio...','["indirecto","exagerado","público","falso"]','indirecto','"Velado" indica que algo se dice de forma encubierta.',NULL,NULL,1,5,223,true),
('es','C2','vocabulary','mcq','«Nimio» significa...','["insignificante","enorme","urgente","brillante"]','insignificante','"Nimio" califica algo de muy escasa importancia.',NULL,NULL,1,5,230,true),
('es','C2','vocabulary','mcq','«Soslayar un problema» significa...','["eludirlo","resolverlo","agravarlo","denunciarlo"]','eludirlo','"Soslayar" es esquivar o pasar por alto.',NULL,NULL,1,5,231,true),
('es','C2','vocabulary','mcq','«Una crítica acerba» es una crítica...','["mordaz e hiriente","amable","neutra","muy breve"]','mordaz e hiriente','"Acerbo" significa áspero, cruel.',NULL,NULL,1,5,232,true),
('es','C2','vocabulary','mcq','«Habida cuenta de» equivale a...','["teniendo en cuenta","a pesar de","con el fin de","salvo que"]','teniendo en cuenta','Locución prepositiva de valor causal.',NULL,NULL,1,5,233,true),
